import csv

stock = {}
with open("stock.csv", newline="") as f:
    for row in csv.DictReader(f):
        stock[row["sku"]] = stock.get(row["sku"], 0) + int(row["qty"])
print(stock)

instruction:
Convert this nested JSON to a flat CSV file:

[
  {"user": {"name": "Ada"}, "orders": 3},
  {"user": {"name": "Grace"}, "orders": 8}
]

output:
import csv, json

rows = []
with open("items.csv", newline="") as f:
    for row in csv.DictReader(f):
        rows.append({
            "id": int(row["id"]),
            "price": float(row["price"]),
            "in_stock": row["in_stock"].lower() == "true",
        })
print(json.dumps(rows, indent=2))

instruction:
Convert this JSON records array to a Markdown table:

[
  {"lang": "Python", "year": 1991},
  {"lang": "JavaScript", "year": 1995}
]

output:
import csv, json

columns = {}
with open("people.csv", newline="") as f:
    for row in csv.DictReader(f):
        for key, value in row.items():
            columns.setdefault(key, []).append(value)
print(json.dumps(columns, indent=2))

